import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E3%81%8A%E4%BE%BF%E3%82%8A%E3%82%B3%E3%83%BC%E3%83%8A%E3%83%BC.html","title":"お便りコーナー","lang":"en-US","frontmatter":{},"git":{"createdTime":1652280129000,"updatedTime":1759318871000,"contributors":[{"name":"Kazuma Arino","username":"","email":"hogeika2@gmail.com","commits":8}]},"readingTime":{"minutes":0.43,"words":130},"filePathRelative":"お便りコーナー.md"}`),a={name:`お便りコーナー.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="お便りコーナー" tabindex="-1"><a class="header-anchor" href="#お便りコーナー"><span>お便りコーナー</span></a></h1><p><a href="./プログラム雑談.html">プログラム雑談</a>にお便りコーナーを作ります。</p><h2 id="告知のブログポスト" tabindex="-1"><a class="header-anchor" href="#告知のブログポスト"><span>告知のブログポスト</span></a></h2><p>基本的な事は以下のブログポストを参考に。</p><p><a href="https://karino2.github.io/2022/05/12/podcast_mail_box.html" target="_blank" rel="noopener noreferrer">プログラム雑談で、お便りのコーナーを始めます - なーんだ、ただの水たまりじゃないか</a></p><h2 id="お便りを受け付けている場所" tabindex="-1"><a class="header-anchor" href="#お便りを受け付けている場所"><span>お便りを受け付けている場所</span></a></h2><p>基本的にはお題箱の以下でpodcastについてのお便りを受け付けます。</p><p><a href="https://odaibako.net/u/karino2012" target="_blank" rel="noopener noreferrer">プログラム雑談のお便り箱</a></p><p>出来たら「ラジオネーム」から始めて、そのままpodcast内で読み上げられるような書き方だと取り上げやすいです。 具体例は上記のブログポスト内の「例」を参照の事。</p><h2 id="募集するお便りの内容" tabindex="-1"><a class="header-anchor" href="#募集するお便りの内容"><span>募集するお便りの内容</span></a></h2><p>podcastで取り上げやすいような内容ならなんでも良いですが、たとえば以下のようなのを想定しています。</p><ul><li>各エピソードへの反応、感想</li><li>プログラムに関するお悩み相談</li><li>取り扱ってほしい話題</li></ul><h2 id="最後に読み上げるテンプレ" tabindex="-1"><a class="header-anchor" href="#最後に読み上げるテンプレ"><span>最後に読み上げるテンプレ</span></a></h2><p>番組で毎回告知的なのを読むのを、テンプレにしたい。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">当番組では、皆様からのお便りを募集しております。</span>
<span class="line">エピソードの感想、プログラム雑談で扱ってほしいテーマ、聞いてみたい事、プログラムに関する質問相談など、</span>
<span class="line">どしどしお寄せください。</span>
<span class="line">宛先は、</span>
<span class="line">https://odaibako.net/u/karino2012</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,15)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};